from pathlib import Path
import json,hashlib,collections,html,math
import numpy as np
R=Path(__file__).resolve().parent;P=R.parent
def read(n):return json.loads((R/n).read_text())
def save(n,x):(R/n).write_text(json.dumps(x,indent=2,ensure_ascii=False),encoding='utf-8')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
e=lambda x:html.escape(str(x))
res=read('RESULTS.json');rows=read('ROWS.json');events=read('EVENTS.json');verification=[]
def suffix(w):return next((s for s in ['edy','eey','ey','y'] if w.endswith(s)),None)
def wilson(k,n):
 z=1.95996398454;p=k/n;d=1+z*z/n;mid=(p+z*z/(2*n))/d;half=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [max(0,mid-half),min(1,mid+half)]
for pp,h in read('FREEZE.json').items():assert sha(Path(pp))==h
for z in res:
 rr=rows[str(z['panel'])];counts=collections.defaultdict(lambda:[0,0,0,0]);ind_events=0
 for r in rr:
  for a,b in zip(r['tokens'],r['tokens'][1:]):
   if not a or not b or not a.startswith(('sh','ch')) or not suffix(a):continue
   ind_events+=1;k=(r['page'],suffix(a) if z['view']=='ending_family' else a[2:]);v=counts[k];cl=0 if a.startswith('sh') else 1;v[cl]+=1;v[cl+2]+=b.startswith('qok')
 page=collections.defaultdict(lambda:[0.,0.])
 for (pg,key),(ns,nc,ss,sc) in counts.items():
  if ns and nc:w=ns*nc/(ns+nc);page[pg][0]+=w*(ss/ns-sc/nc);page[pg][1]+=w
 T=sum(a/b for a,b in page.values())/len(page) if page else 0.;assert abs(T-z['observed']['T'])<1e-12
 assert ind_events==sum(x['panel']==z['panel'] for x in events)
 null=np.load(R/f"panel{z['panel']}-{z['null']}-null.npz")[z['view']];k=int(sum(null>=T-1e-12));assert abs((1+k)/(len(null)+1)-z['p_upper'])<1e-12;assert abs(min(1,z['p_upper']*16)-z['p_adjusted'])<1e-12
 ci=wilson(k,len(null));verification.append(dict(panel=z['panel'],view=z['view'],null=z['null'],observed_direct_recomputed=True,exceedances=k,N=len(null),p_adjusted=z['p_adjusted'],MC_95_interval_adjusted=[min(1,16*x) for x in ci]))
save('VERIFICATION.json',dict(input_code_hashes_unchanged=True,all16_observed_statistics_independently_recomputed=True,event_denominators_reconciled=True,all16_saved_null_p_values_recomputed=True,details=verification,limits='Monte Carlo intervals describe simulated-tail uncertainty under frozen nulls, not uncertainty of the manuscript effect or historical interpretation. Family selection was retrospective.'))
primary=[z for z in res if z['view']=='ending_family' and z['null']=='whole_line'];fixed=[z for z in res if z['view']=='ending_family' and z['null']=='fixed_endpoints'];bodytests=[z for z in res if z['view']=='exact_body']
save('HANDOFF-UPDATE.json',dict(result='Bath matched-ending association reproduced across H/F under both declared shuffles at point estimates; starred positive but fails16-comparison adjustment. Stricter exact-body result does not pass consistently across H/F.',model='Page-level ch/sh usage proportions and a within-page local association can coexist. A page-only spelling setting is incomplete as a full account. No inference that choosing sh causally changes the next word, or that the association is necessarily grammatical.',readings='H/F alternate readings of same manuscript; transcription robustness, not independent replication. Shared loci, same B/P strata, unknown barriers retained.',page_denominator='H starred15positive,6negative,1tie:15/21 if ties omitted,15/22 eligible pages if retained. F14positive,7negative,1tie. Ties retained in means; original Claude inline estimator unavailable.',stronger_control='Exact-body removes differences in the rest of the word after ch/sh. H bath point estimates pass, F bath does not after correction. H bath fixed-endpoint p.048 is Monte Carlo borderline. Do not claim universal prefix-only effect.',qualification='PASS720exact toy orbit /1440optimized-vs-direct scores; unknown/line/endpoints/multisets checked;24-line strong planted matched-body signal passes bothnulls; no-qok controlT0/p1. Limited arithmetic/invariants/one-generator sensitivity, not semantic qualification.',prior_gap='Existing v78 bothreadings/2panels/2views nonepassfullsearchcorrection. Lag-survival/failure does not separate grammar versus junction as exhaustive mechanisms.',next='Among e-run versus herbal-zodiac links, prefer a frozen e-run structural test with hand/section/format/transcription controls. Label-versus-paragraph contrast alone is confounded. No new e-run or vocabulary-link score performed in this audit.'))
body='<h1>sh/ch → qok · matched endings, then matched word bodies</h1><p><b>The bath association reproduces across H and F; the stronger two-scribe grammar claim does not qualify.</b> Matched-ending bath gaps are+10.8pp H and+8.7pp F. Starred gaps are positive, but fail the declared comparison correction. Exact-body matching yields a mixed bath result across transcriptions.</p><p>This is retrospective structural research. The suffix rule was exposed before this audit; freezing the execution cannot make it an untouched confirmatory test. H/F represent the same manuscript. Claude’s /tmp/claude-0/s/gap.py and inline checks are not accessible in this Windows workspace, so this is a specified audit rather than exact code reproduction.</p>'
body+='<h2>Primary within-line word shuffle</h2><p>Literal initial sh/ch; longest suffix matching edy,eey,ey,y. Compare next-token qok rates within each page AND suffix family, weight family differences by ns·nc/(ns+nc), then give eligible pages equal weight. Source-last/unknown-followed origins are ineligible. Each of4panels uses shared H/F source loci, known hand, CurrierB and paragraph-formatP; no labels or other hands pooled. All original folios including f75 retained.</p><table><tr><th>Panel</th><th>Reading</th><th>Positive / eligible pages</th><th>Mean gap pp</th><th>Raw p</th><th>Adjusted p</th></tr>'
for z in primary:
 o=z['observed'];body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [z['section']+' hand'+z['hand'],z['reading'],str(o['positive_pages'])+'/'+str(o['eligible_pages']),f"{100*o['T']:+.2f}",f"{z['p_upper']:.4f}",f"{z['p_adjusted']:.4f}"])+'</tr>'
body+='</table><p>4,999shuffles perpanel/null. Primary permutations move complete words within contiguous readable line spans, preserving each line’s words and unknown slots. No line/unknown bridging. One-sided Monte Carlo p=(1+exceedances)/5,000; Bonferroni16 covers4panels×2matching views×2null policies. It does not correct the entire prior exploratory research history. These are null-model arrangement results, not probabilities that a grammar hypothesis is true.</p><p>Starred H has15positive pages,6negative and1tie (f105v):15/21 when omitting ties,15/22 eligible pages here. F has14positive,7negative,1tie. Thus the quoted H sign count is compatible with excluding a tie; it is not evidence of a lost page. The mean estimator and randomization differ from the unavailable inline checks.</p>'
body+='<h2>Endpoint-preserving sensitivity</h2><p>This uses the same source-first/source-last and uncertainty-barrier bucket policy as v75/v78. It preserves broad endpoint placement while leaving exact interior positions free. Bath point estimates retain support; starred does not.</p><table><tr><th>Panel / reading</th><th>Gap pp</th><th>Adjusted p</th><th>Monte Carlo95% interval for adjusted tail</th></tr>'
for z in fixed:
 vv=next(v for v in verification if v['panel']==z['panel'] and v['view']==z['view'] and v['null']==z['null']);body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [z['section']+' '+z['reading'],f"{100*z['observed']['T']:+.2f}",f"{z['p_adjusted']:.4f}",'–'.join(f'{x:.4f}' for x in vv['MC_95_interval_adjusted'])])+'</tr>'
body+='</table><p>Finite Monte Carlo precision matters near.05: F bath fixed-endpoint point p=.032 has an interval crossing.05. No further draws were added to force a pass. Primary whole-line bath results are clearer. Tail intervals are simulation uncertainty, not confidence intervals for the manuscript’s mean gap.</p>'
body+='<h2>Does matching the whole remaining word change the conclusion?</h2><p>Broad suffix matching does not isolate sh itself: different stems/vocabulary can remain. The predeclared stricter view compares exact bodies after initial ch/sh on the same page, such as shedy versus chedy. H bath retains a positive qualified point estimate, but F bath does not pass correction; hence no claim that a prefix-only effect has qualified across both readings. Negative tests do not establish absence or power against every effect.</p><table><tr><th>Panel / reading</th><th>Gap pp</th><th>Whole-line adjusted p</th><th>Fixed-endpoint adjusted p</th></tr>'
for z in bodytests:
 if z['null']!='whole_line':continue
 zf=next(x for x in bodytests if x['panel']==z['panel'] and x['null']=='fixed_endpoints');body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [z['section']+' '+z['reading'],f"{100*z['observed']['T']:+.2f}",f"{z['p_adjusted']:.4f}",f"{zf['p_adjusted']:.4f}"])+'</tr>'
body+='</table><p>H bath exact-body endpoint p=.048 is borderline at this Monte Carlo resolution. It must not be described as a stable threshold crossing. Exact-body matching can change which groups and opportunities contribute, so gaps need not monotonically shrink.</p>'
body+='<h2>Page settings and local association coexist descriptively</h2><p>The fraction sh among all initial-sh/ch tokens varies across pages: H bath37.5–59.0%, F bath36.6–60.9%; H starred11.5–56.8%, F starred11.6–58.3%. These are observed use proportions, not inferred causal settings. Both nulls preserve page-level prefix frequencies. The supported bath contrast therefore needs more than that page proportion alone.</p><p>A context-conditioned spelling choice can correlate with a following word. So can collocation, grammatical adjacency, a graphic/junction convention, copying or notation. Association does not establish that choosing sh changes the next word, or identify either unit as a thing or an action. The updated model is page preference plus a local conditional association, with mechanism unresolved.</p>'
body+='<h2>The one-word-gap question was already tested</h2><p><a href="../one-gap-order-v78/report.html">Existing qualified v78 audit</a> retains bath H75/79 and F73/77 forward/reverse gap counts, and starred H85/56 and F88/57; all full-opening-search corrected p-values are1. Its target-middle exclusion sensitivity also did not pass. This is not evidence that every nonlocal effect is absent. First-order local chaining can generate gap effects, and genuine grammatical relations can require adjacency. Lag tests cannot decide a grammar-versus-junction dichotomy.</p>'
body+='<h2>Qualification, coverage and every page</h2><p>Before manuscript scores, the optimized statistic agreed with independent direct counting over all720permutations of an authored6-word line, for bothmatching views (1,440checks). Exact-orbit tail ranks obeyed nominal and16-adjusted bounds. Two null policies preserved authored line multisets, unknown slots and required endpoints. A24-line planted local matched-body fixture scored1 and passed the correction under both nulls; a no-qok fixture gives0/p1. This establishes arithmetic, invariants and one strong planted signal, not general power or linguistic semantics.</p>'
for z in primary:
 body+='<details><summary>'+e(z['section']+' '+z['reading'])+' · all page gaps and sh use</summary><table><tr><th>Page</th><th>Eligible</th><th>Gap pp</th><th>sh share</th></tr>'
 for p in z['observed']['pages']:body+='<tr>'+''.join('<td>'+e(v)+'</td>' for v in [p['page'],p['eligible'],'—' if p['gap'] is None else f"{100*p['gap']:+.2f}",'—' if p['sh_share'] is None else f"{100*p['sh_share']:.1f}%"])+'</tr>'
 body+='</table></details>'
body+='<h2>Next</h2><p>Between the proposed e-run test and herbal-to-zodiac links, the e-run structural comparison is the cheaper next project. Freeze the run-count rule and control scribe, section, format and transcription. A pooled recipes-versus-labels contrast alone would mix those factors. No new e-run or vocabulary-link score was run here.</p><h2>Records</h2>'
for n in ['PROTOCOL.json','FREEZE.json','QUALIFICATION.json','SUMMARY.json','RESULTS.json','ROWS.json','EVENTS.json','VERIFICATION.json','HANDOFF-UPDATE.json']:
 body+='<p><a href="'+n+'">'+n+'</a></p>'
(R/'report.html').write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>sh/ch–qok qualification · Reed v94</title><style>body{font:17px system-ui;line-height:1.6;max-width:1100px;margin:40px auto;padding:0 20px;background:#f6f2e8;color:#173c38}table{border-collapse:collapse;width:100%;font-size:15px}td,th{border:1px solid #abc;padding:8px;text-align:left}h1,h2{line-height:1.2}h2{margin-top:2em}details{padding:10px;border-bottom:1px solid #abc}a{color:#126151}</style>'+body+'</html>',encoding='utf-8')
save('SHA256SUMS.json',{p.name:sha(p) for p in R.iterdir() if p.is_file() and p.name!='SHA256SUMS.json'});print('Independent counts and all saved null p-values verified; report saved. HTML appearance unreviewed.')
